1) DEFAULT NULL , LBR_PropIE VARCHAR(14) DEFAULT NULL , LBR_PropName VARCHAR(60) DEFAULT NULL , LBR_PropRNTRC VARCHAR(8) DEFAULT NULL , LBR_PropUF_ID NUMERIC(10) DEFAULT NULL , LBR_Protocol VARCHAR(15) DEFAULT NULL , LBR_QrCodMDFe VARCHAR(1000) DEFAULT NULL , LBR_QtyCargo NUMERIC DEFAULT NULL , LBR_QtyCTe NUMERIC(10) DEFAULT NULL , LBR_QtyMDFe NUMERIC(10) DEFAULT NULL , LBR_QtyNFe NUMERIC(10) DEFAULT NULL , LBR_Recibo VARCHAR(15) DEFAULT NULL , LBR_Renavam VARCHAR(11) DEFAULT NULL , LBR_RespTecCNPJ VARCHAR(14) DEFAULT NULL , LBR_RespTecContact VARCHAR(60) DEFAULT NULL , LBR_RespTecEMail VARCHAR(60) DEFAULT NULL , LBR_RespTecPhone VARCHAR(12) DEFAULT NULL , LBR_RNTRC VARCHAR(8) DEFAULT NULL , LBR_Serie VARCHAR(3) DEFAULT '1', LBR_Tara NUMERIC(10) DEFAULT NULL , LBR_tpAmb CHAR(1) DEFAULT NULL , LBR_tpCar VARCHAR(2) DEFAULT NULL , LBR_tpCarga VARCHAR(2) DEFAULT NULL , LBR_tpEmis CHAR(1) DEFAULT '1', LBR_tpEmit CHAR(1) DEFAULT NULL , LBR_tpProp CHAR(1) DEFAULT NULL , LBR_tpRod VARCHAR(2) DEFAULT NULL , LBR_tpTransp CHAR(1) DEFAULT NULL , LBR_UFFim_ID NUMERIC(10) DEFAULT NULL , LBR_UFIni_ID NUMERIC(10) DEFAULT NULL , LBR_ValueCargo NUMERIC DEFAULT NULL , LBR_VeicUF_ID NUMERIC(10) DEFAULT NULL , LBR_verProc VARCHAR(20) DEFAULT NULL , LBR_xMotivo VARCHAR(255) DEFAULT NULL , Processed CHAR(1) NOT NULL CHECK (Processed IN ('Y','N')) DEFAULT 'N', ProcessedOn NUMERIC DEFAULT NULL , Processing CHAR(1) NOT NULL CHECK (Processing IN ('Y','N')) DEFAULT 'N', Updated TIMESTAMP NOT NULL, UpdatedBy NUMERIC(10) NOT NULL, CONSTRAINT LBR_MDFe_Key PRIMARY KEY (LBR_MDFe_ID), CONSTRAINT LBR_MDFe_UU_idx UNIQUE (LBR_MDFe_UU));

